WITH RECURSIVE explore AS (
  SELECT '{root}' as path, v.* FROM shipments s, jsonb_each(s.shipment_overview) as e(k,v)
  UNION ALL
  SELECT e.path || '.' || k, j.* FROM explore e, jsonb_each(e.v) as j(k,v) WHERE jsonb_typeof(e.v) = 'object'
)
SELECT DISTINCT path FROM explore ORDER BY path;

